// Standard stream plumbing that reproduces CPython's stdio buffering.
//
// CPython line-buffers stdout when it is attached to a TTY and block-buffers it
// otherwise, while stderr stays unbuffered. That difference is observable: when
// both streams are redirected into the same pipe, an unhandled traceback shows
// up *before* the stdout lines that were logically printed earlier, because the
// stdout buffer is only drained at interpreter shutdown.
import { writeSync } from 'node:fs';

const blockBuffered = !process.stdout.isTTY;

let pending = [];

export function stdoutWrite(text) {
  if (blockBuffered) {
    pending.push(text);
    return;
  }
  process.stdout.write(text);
}

export function stderrWrite(text) {
  // stderr is unbuffered in CPython: write it out immediately.
  rawWrite(2, text);
}

// Drains the stdout buffer. Called explicitly at every interpreter exit point
// so the flush is ordered *after* any traceback that went to stderr.
export function flushStdout() {
  if (pending.length === 0) return;
  const text = pending.join('');
  pending = [];
  rawWrite(1, text);
}

function rawWrite(fd, text) {
  const buf = Buffer.from(text, 'utf8');
  let offset = 0;
  while (offset < buf.length) {
    try {
      offset += writeSync(fd, buf, offset, buf.length - offset);
    } catch (err) {
      if (err.code === 'EAGAIN') continue; // non-blocking pipe: retry
      if (err.code === 'EPIPE') return; // reader went away, like SIGPIPE
      throw err;
    }
  }
}

// Backstop in case an exit path forgets to flush.
process.on('exit', flushStdout);

