// Python exception shims.
//
// Every exception carries the two pieces of metadata the traceback renderer
// needs: `pyName`, the dotted name CPython prints on the final line, and
// `pyFrame`, the location of the `raise` statement inside the library.

export class PyException extends Error {
  constructor(message, { pyName, pyFrame } = {}) {
    super(message);
    this.pyName = pyName ?? new.target.name;
    this.pyFrame = pyFrame ?? null;
  }
}

export class TypeError_ extends PyException {
  constructor(message) {
    super(message, { pyName: 'TypeError' });
  }
}

export class ValueError extends PyException {
  constructor(message) {
    super(message, { pyName: 'ValueError' });
  }
}

// Raised to unwind out of `main` the way CPython's SystemExit does. The entry
// point turns it into a process exit status instead of a traceback.
export class SystemExit extends PyException {
  constructor(code = 0) {
    super(`SystemExit: ${code}`, { pyName: 'SystemExit' });
    this.code = code;
  }
}

export function isPyException(err) {
  return err instanceof PyException;
}

