// The handful of Python builtins the translated script relies on.
import { stdoutWrite } from './io.mjs';

// str(): dispatches to a __str__ hook when the object defines one, and falls
// back to repr() for containers, matching CPython.
export function pyStr(value) {
  if (value === null || value === undefined) return 'None';
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (typeof value === 'number') return pyNumberStr(value);
  if (typeof value === 'string') return value;
  if (typeof value === 'object' && typeof value.__str__ === 'function') {
    return value.__str__();
  }
  return pyRepr(value);
}

// repr(): only the cases the script can actually reach.
export function pyRepr(value) {
  if (value === null || value === undefined) return 'None';
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (typeof value === 'number') return pyNumberStr(value);
  if (typeof value === 'string') return pyStringRepr(value);
  if (typeof value === 'object' && typeof value.__repr__ === 'function') {
    return value.__repr__();
  }
  if (Array.isArray(value)) return pyTupleRepr(value);
  if (value instanceof Map) return pyDictRepr(value);
  if (typeof value === 'function') return `<function ${value.__name__ ?? value.name}>`;
  return String(value);
}

// repr() of a tuple: note the trailing comma on the 1-element form.
export function pyTupleRepr(items) {
  if (items.length === 0) return '()';
  if (items.length === 1) return `(${pyRepr(items[0])},)`;
  return `(${items.map(pyRepr).join(', ')})`;
}

// repr() of a dict; insertion ordered, as dicts have been since 3.7.
export function pyDictRepr(entries) {
  const pairs = entries instanceof Map ? [...entries.entries()] : Object.entries(entries);
  if (pairs.length === 0) return '{}';
  return `{${pairs.map(([k, v]) => `${pyRepr(k)}: ${pyRepr(v)}`).join(', ')}}`;
}

function pyStringRepr(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let out = '';
  for (const ch of text) {
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += `\\${ch}`;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else out += ch;
  }
  return quote + out + quote;
}

function pyNumberStr(value) {
  if (Number.isInteger(value)) return String(value);
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';
  return String(value);
}

export function print(...values) {
  stdoutWrite(values.map(pyStr).join(' ') + '\n');
}

export function len(value) {
  if (typeof value === 'string' || Array.isArray(value)) return value.length;
  if (value instanceof Map || value instanceof Set) return value.size;
  if (typeof value?.__len__ === 'function') return value.__len__();
  return Object.keys(value).length;
}

