// functools.partial / functools.update_wrapper, enough of them for Job.do().
//
// schedule stores the user callback as a partial and then prints the partial's
// `args` tuple and `keywords` dict, so those attributes have to survive.

export function partial(func, args = [], keywords = new Map()) {
  const bound = (...extra) => func(...args, ...extra, keywords);
  bound.func = func;
  bound.args = args;
  bound.keywords = keywords instanceof Map ? keywords : new Map(Object.entries(keywords));
  return bound;
}

// Copies __name__ (and friends) from the wrapped callable onto the wrapper.
// functools.partial objects have no __name__ of their own, which is why
// schedule has to call this before reading job_func.__name__.
export function updateWrapper(wrapper, wrapped) {
  wrapper.__name__ = wrapped.__name__ ?? (wrapped.name || '<lambda>');
  wrapper.__qualname__ = wrapped.__qualname__ ?? wrapper.__name__;
  wrapper.__doc__ = wrapped.__doc__ ?? null;
  return wrapper;
}

// Tags a JS function so it reports itself as a Python lambda. Anonymous arrow
// functions get an empty `name` in JS, but CPython names every lambda
// "<lambda>", and that name is what shows up in a Job's str().
export function lambda(func) {
  func.__name__ = '<lambda>';
  return func;
}

