// Minimal datetime.datetime / datetime.time / datetime.timedelta.
//
// The scheduler needs real date arithmetic to compute next_run values, so these
// mirror the semantics Python relies on: timedeltas are exact, replace() is
// field-wise, and comparison is chronological. All values are naive local time.

const MICROS_PER_SECOND = 1_000_000;

export class TimeDelta {
  // Accepts the same keyword units schedule passes: timedelta(**{unit: n}).
  constructor({ weeks = 0, days = 0, hours = 0, minutes = 0, seconds = 0, microseconds = 0 } = {}) {
    this.totalMicroseconds = Math.round(
      ((((weeks * 7 + days) * 24 + hours) * 60 + minutes) * 60 + seconds) * MICROS_PER_SECOND +
        microseconds
    );
  }

  static fromMicroseconds(micros) {
    const delta = new TimeDelta();
    delta.totalMicroseconds = Math.round(micros);
    return delta;
  }

  // timedelta.days floors toward negative infinity, like Python.
  get days() {
    return Math.floor(this.totalMicroseconds / (86400 * MICROS_PER_SECOND));
  }

  totalSeconds() {
    return this.totalMicroseconds / MICROS_PER_SECOND;
  }

  add(other) {
    return TimeDelta.fromMicroseconds(this.totalMicroseconds + other.totalMicroseconds);
  }

  sub(other) {
    return TimeDelta.fromMicroseconds(this.totalMicroseconds - other.totalMicroseconds);
  }

  gt(other) {
    return this.totalMicroseconds > other.totalMicroseconds;
  }
}

export class Time {
  constructor(hour = 0, minute = 0, second = 0, microsecond = 0) {
    this.hour = hour;
    this.minute = minute;
    this.second = second;
    this.microsecond = microsecond;
  }

  // str(time) is "HH:MM:SS", with ".ffffff" appended only when non-zero.
  __str__() {
    const base = `${pad2(this.hour)}:${pad2(this.minute)}:${pad2(this.second)}`;
    return this.microsecond ? `${base}.${String(this.microsecond).padStart(6, '0')}` : base;
  }

  __repr__() {
    return `datetime.time(${this.hour}, ${this.minute}, ${this.second})`;
  }

  key() {
    return ((this.hour * 60 + this.minute) * 60 + this.second) * MICROS_PER_SECOND + this.microsecond;
  }

  gt(other) {
    return this.key() > other.key();
  }
}

export class DateTime {
  constructor(date, microsecond = 0) {
    this.date = new Date(date.getTime());
    this.date.setMilliseconds(0);
    this.microsecond = microsecond;
  }

  static now() {
    const now = new Date();
    return new DateTime(now, now.getMilliseconds() * 1000);
  }

  get hour() {
    return this.date.getHours();
  }

  get minute() {
    return this.date.getMinutes();
  }

  get second() {
    return this.date.getSeconds();
  }

  time() {
    return new Time(this.hour, this.minute, this.second, this.microsecond);
  }

  add(delta) {
    const micros = this.microsecond + delta.totalMicroseconds;
    const carrySeconds = Math.floor(micros / MICROS_PER_SECOND);
    const rest = micros - carrySeconds * MICROS_PER_SECOND;
    return new DateTime(new Date(this.date.getTime() + carrySeconds * 1000), rest);
  }

  sub(other) {
    if (other instanceof TimeDelta) return this.add(TimeDelta.fromMicroseconds(-other.totalMicroseconds));
    const seconds = (this.date.getTime() - other.date.getTime()) / 1000;
    return TimeDelta.fromMicroseconds(seconds * MICROS_PER_SECOND + (this.microsecond - other.microsecond));
  }

  // datetime.replace(): only the named fields change.
  replace({ hour, minute, second, microsecond } = {}) {
    const next = new Date(this.date.getTime());
    if (hour !== undefined) next.setHours(hour);
    if (minute !== undefined) next.setMinutes(minute);
    if (second !== undefined) next.setSeconds(second);
    return new DateTime(next, microsecond !== undefined ? microsecond : this.microsecond);
  }

  strftime() {
    const d = this.date;
    return (
      `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())} ` +
      `${pad2(d.getHours())}:${pad2(d.getMinutes())}:${pad2(d.getSeconds())}`
    );
  }
}

function pad2(value) {
  return String(value).padStart(2, '0');
}

