// A single scheduled job: the interval/unit fluent builder, the `at()` time
// parser, and the next-run computation.
import { DateTime, Time, TimeDelta } from '../py/datetime.mjs';
import { partial, updateWrapper } from '../py/functools.mjs';
import { pyStr } from '../py/builtins.mjs';
import { TypeError_ } from '../py/exceptions.mjs';
import { IntervalError, RAISE_SITES, ScheduleError, ScheduleValueError } from './errors.mjs';

const VALID_UNITS = ['seconds', 'minutes', 'hours', 'days', 'weeks'];
const WEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];

// Time strings accepted by at(), per unit. Note that the daily pattern allows an
// hour of 20-29: values above 23 pass the regex and are rejected later by the
// range check, which is what produces two distinct error messages.
const DAILY_TIME = /^[0-2]\d:[0-5]\d(:[0-5]\d)?$/;
const HOURLY_TIME = /^([0-5]\d)?:[0-5]\d$/;
const MINUTELY_TIME = /^:[0-5]\d$/;

export class Job {
  constructor(interval, scheduler = null) {
    this.interval = interval; // pause interval * unit between runs
    this.latest = null; // upper limit to the interval
    this.job_func = null; // the job job_func to run
    this.unit = null; // time units, e.g. 'minutes', 'hours', ...
    this.at_time = null; // optional time at which this job runs
    this.last_run = null; // datetime of the last run
    this.next_run = null; // datetime of the next run
    this.period = null; // timedelta between runs, only valid for
    this.start_day = null; // Specific day of the week to start on
    this.cancel_after = null; // datetime after which to cancel the job
    this.tags = new Set(); // unique set of tags for the job
    this.scheduler = scheduler; // scheduler to register with
  }

  // Jobs sort by next_run so the scheduler can peek at the head of the queue.
  lt(other) {
    return this.next_run.date.getTime() < other.next_run.date.getTime();
  }

  __repr__() {
    const formatTime = (t) => (t ? t.strftime() : '[never]');
    const timestats = `(last run: ${formatTime(this.last_run)}, next run: ${formatTime(this.next_run)})`;
    const jobFuncName = this.#jobFuncName();
    const callArgs = this.job_func ? [...this.job_func.args].map(pyStr) : [];
    const callKwargs = this.job_func
      ? [...this.job_func.keywords.entries()].map(([k, v]) => `${k}=${pyStr(v)}`)
      : [];
    const callRepr = `${jobFuncName}(${[...callArgs, ...callKwargs].join(', ')})`;

    if (this.at_time !== null) {
      return `Every ${this.interval} ${this.#unitName()} at ${pyStr(this.at_time)} do ${callRepr} ${timestats}`;
    }
    if (this.start_day !== null) {
      return `Every ${this.interval} ${this.start_day} do ${callRepr} ${timestats}`;
    }
    return `Every ${this.interval} ${this.#unitName()} do ${callRepr} ${timestats}`;
  }

