  __str__() {
    return (
      `Job(interval=${pyStr(this.interval)}, ` +
      `unit=${pyStr(this.unit)}, ` +
      `do=${this.#jobFuncName()}, ` +
      `args=${pyStr(this.job_func ? this.job_func.args : null)}, ` +
      `kwargs=${pyStr(this.job_func ? this.job_func.keywords : null)})`
    );
  }

  #jobFuncName() {
    if (this.job_func === null) return pyStr(null);
    return this.job_func.__name__ ?? String(this.job_func);
  }

  #unitName() {
    // "1 second" but "2 seconds".
    return this.interval === 1 ? this.unit.slice(0, -1) : this.unit;
  }

  get second() {
    if (this.interval !== 1) throw new IntervalError('Use seconds instead of second');
    return this.seconds;
  }

  get seconds() {
    this.unit = 'seconds';
    return this;
  }

  get minute() {
    if (this.interval !== 1) throw new IntervalError('Use minutes instead of minute');
    return this.minutes;
  }

  get minutes() {
    this.unit = 'minutes';
    return this;
  }

  get hour() {
    if (this.interval !== 1) throw new IntervalError('Use hours instead of hour');
    return this.hours;
  }

  get hours() {
    this.unit = 'hours';
    return this;
  }

  get day() {
    if (this.interval !== 1) throw new IntervalError('Use days instead of day');
    return this.days;
  }

  get days() {
    this.unit = 'days';
    return this;
  }

  get week() {
    if (this.interval !== 1) throw new IntervalError('Use weeks instead of week');
    return this.weeks;
  }

  get weeks() {
    this.unit = 'weeks';
    return this;
  }

  get monday() {
    return this.#startDay('monday');
  }

  get tuesday() {
    return this.#startDay('tuesday');
  }

  get wednesday() {
    return this.#startDay('wednesday');
  }

  get thursday() {
    return this.#startDay('thursday');
  }

  get friday() {
    return this.#startDay('friday');
  }

  get saturday() {
    return this.#startDay('saturday');
  }

  get sunday() {
    return this.#startDay('sunday');
  }

  #startDay(name) {
    if (this.interval !== 1) {
      throw new ScheduleValueError(`Scheduling .${name}() jobs is only allowed for weekly jobs. Using .${name}() on a job scheduled to run every 2 or more weeks is not supported.`);
