    this.start_day = name;
    return this.weeks;
  }

  tag(...tags) {
    for (const t of tags) this.tags.add(t);
    return this;
  }

  // Pins the time of day (or of the hour/minute) at which the job runs.
  at(timeStr) {
    if (!VALID_UNITS.slice(2).includes(this.unit) && !this.start_day) {
      // 'hours', 'days' — plus 'minutes', checked below.
      if (this.unit !== 'minutes') {
        throw new ScheduleValueError(
          'Invalid unit (valid units are `days`, `hours`, and `minutes`)',
          RAISE_SITES.atInvalidUnit
        );
      }
    }
    if (typeof timeStr !== 'string') {
      throw new TypeError_('at() should be passed a string');
    }
