      if (!DAILY_TIME.test(timeStr)) {
        throw new ScheduleValueError(
          'Invalid time format for a daily job (valid format is HH:MM(:SS)?)',
          RAISE_SITES.atDailyFormat
        );
      }
    }
    if (this.unit === 'hours' && !HOURLY_TIME.test(timeStr)) {
      throw new ScheduleValueError(
        'Invalid time format for an hourly job (valid format is (MM)?:SS)',
        RAISE_SITES.atHourlyFormat
      );
    }
    if (this.unit === 'minutes' && !MINUTELY_TIME.test(timeStr)) {
      throw new ScheduleValueError(
        'Invalid time format for a minutely job (valid format is :SS)',
        RAISE_SITES.atMinutelyFormat
      );
    }

    const timeValues = timeStr.split(':');
    let hour;
    let minute;
    let second;
    if (timeValues.length === 3) {
      [hour, minute, second] = timeValues;
    } else if (timeValues.length === 2 && this.unit === 'minutes') {
      hour = '0';
      minute = '0';
      second = timeValues[1];
    } else if (timeValues.length === 2 && this.unit === 'hours' && timeValues[0].length) {
      hour = '0';
      [minute, second] = timeValues;
    } else {
      [hour, minute] = timeValues;
      second = '0';
    }

    if (this.unit === 'days' || this.start_day) {
      const hourValue = parseInt(hour, 10);
      if (!(hourValue >= 0 && hourValue <= 23)) {
        // Upstream forgets to interpolate the offending value here, so the
        // literal "{}" placeholder is part of the message.
        throw new ScheduleValueError(
          'Invalid number of hours ({} is not between 0 and 23)',
          RAISE_SITES.atHourRange
        );
      }
    } else if (this.unit === 'hours') {
      hour = '0';
    } else if (this.unit === 'minutes') {
      hour = '0';
      minute = '0';
    }
    this.at_time = new Time(parseInt(hour, 10), parseInt(minute, 10), parseInt(second, 10));
    return this;
  }

  // Registers `func` with the scheduler and returns the job, so callers can keep
  // a handle for cancel_job().
  do(func, args = [], kwargs = new Map()) {
    this.job_func = partial(func, args, kwargs);
    updateWrapper(this.job_func, func);
    this.#scheduleNextRun();
    if (this.scheduler === null) {
      throw new ScheduleError('Unable to a add job to schedule. Job is not associated with an scheduler');
    }
    this.scheduler.jobs.push(this);
    return this;
  }

  get should_run() {
    return this.next_run !== null && DateTime.now().sub(this.next_run).totalMicroseconds >= 0;
  }

  run() {
    this.last_run = DateTime.now();
    const result = this.job_func();
    this.#scheduleNextRun();
    return result;
  }

  #scheduleNextRun() {
    if (!VALID_UNITS.includes(this.unit)) {
      throw new ScheduleValueError(
        `Invalid unit (valid units are ${VALID_UNITS.map((u) => `'${u}'`).join(', ')})`,
        RAISE_SITES.scheduleNextRunUnit
      );
    }

    let interval;
    if (this.latest !== null) {
      if (this.latest < this.interval) {
        throw new ScheduleError('`latest` is greater than `interval`');
      }
      interval = this.interval + Math.floor(Math.random() * (this.latest - this.interval + 1));
    } else {
      interval = this.interval;
    }

    this.period = new TimeDelta({ [this.unit]: interval });
    this.next_run = DateTime.now().add(this.period);

    if (this.start_day !== null) {
      if (this.unit !== 'weeks') throw new ScheduleValueError("`unit` should be 'weeks'");
      const weekday = WEEKDAYS.indexOf(this.start_day);
      if (weekday < 0) {
        throw new ScheduleValueError(`Invalid start day (valid start days are ${WEEKDAYS.join(', ')})`);
      }
      // Python's weekday() is Monday-based; JS getDay() is Sunday-based.
      let daysAhead = weekday - ((this.next_run.date.getDay() + 6) % 7);
      if (daysAhead <= 0) daysAhead += 7; // target day already happened this week
      this.next_run = this.next_run.add(new TimeDelta({ days: daysAhead })).sub(this.period);
    }

    if (this.at_time !== null) {
      if (!['days', 'hours', 'minutes'].includes(this.unit) && this.start_day === null) {
        throw new ScheduleValueError('Invalid unit without specifying start day');
      }
      const fields = { second: this.at_time.second, microsecond: 0 };
      if (this.unit === 'days' || this.start_day !== null) fields.hour = this.at_time.hour;
      if (['days', 'hours'].includes(this.unit) || this.start_day !== null) {
        fields.minute = this.at_time.minute;
      }
      this.next_run = this.next_run.replace(fields);

      // Also run at the specified time *today* (or *this hour*): a job that
      // overran its period would otherwise skip a slot.
      if (this.last_run === null || this.next_run.sub(this.last_run).gt(this.period)) {
        const now = DateTime.now();
        if (this.unit === 'days' && this.at_time.gt(now.time()) && this.interval === 1) {
          this.next_run = this.next_run.sub(new TimeDelta({ days: 1 }));
        } else if (
          this.unit === 'hours' &&
          (this.at_time.minute > now.minute ||
            (this.at_time.minute === now.minute && this.at_time.second > now.second))
        ) {
          this.next_run = this.next_run.sub(new TimeDelta({ hours: 1 }));
        } else if (this.unit === 'minutes' && this.at_time.second > now.second) {
          this.next_run = this.next_run.sub(new TimeDelta({ minutes: 1 }));
        }
      }
    }

    if (this.start_day !== null && this.at_time !== null) {
      // Check whether we can still make today's slot.
      if (this.next_run.sub(DateTime.now()).days >= 7) {
        this.next_run = this.next_run.sub(this.period);
      }
    }
  }
}

