    this.#scheduleNextRun();
    if (this.scheduler === null) {
      throw new ScheduleError('Unable to a add job to schedule. Job is not associated with an scheduler');
    }
    this.scheduler.jobs.push(this);
    return this;
  }

  get should_run() {
    return this.next_run !== null && DateTime.now().sub(this.next_run).totalMicroseconds >= 0;
  }

  run() {
    this.last_run = DateTime.now();
    const result = this.job_func();
    this.#scheduleNextRun();
    return result;
  }

  #scheduleNextRun() {
    if (!VALID_UNITS.includes(this.unit)) {
      throw new ScheduleValueError(
        `Invalid unit (valid units are ${VALID_UNITS.map((u) => `'${u}'`).join(', ')})`,
        RAISE_SITES.scheduleNextRunUnit
      );
    }

    let interval;
    if (this.latest !== null) {
      if (this.latest < this.interval) {
        throw new ScheduleError('`latest` is greater than `interval`');
      }
      interval = this.interval + Math.floor(Math.random() * (this.latest - this.interval + 1));
    } else {
      interval = this.interval;
    }

    this.period = new TimeDelta({ [this.unit]: interval });
    this.next_run = DateTime.now().add(this.period);

    if (this.start_day !== null) {
      if (this.unit !== 'weeks') throw new ScheduleValueError("`unit` should be 'weeks'");
      const weekday = WEEKDAYS.indexOf(this.start_day);
      if (weekday < 0) {
