      // overran its period would otherwise skip a slot.
      if (this.last_run === null || this.next_run.sub(this.last_run).gt(this.period)) {
        const now = DateTime.now();
        if (this.unit === 'days' && this.at_time.gt(now.time()) && this.interval === 1) {
          this.next_run = this.next_run.sub(new TimeDelta({ days: 1 }));
        } else if (
          this.unit === 'hours' &&
          (this.at_time.minute > now.minute ||
            (this.at_time.minute === now.minute && this.at_time.second > now.second))
        ) {
          this.next_run = this.next_run.sub(new TimeDelta({ hours: 1 }));
        } else if (this.unit === 'minutes' && this.at_time.second > now.second) {
          this.next_run = this.next_run.sub(new TimeDelta({ minutes: 1 }));
        }
      }
    }

    if (this.start_day !== null && this.at_time !== null) {
      // Check whether we can still make today's slot.
      if (this.next_run.sub(DateTime.now()).days >= 7) {
