// The job registry. Owns the job list and the run/cancel/clear operations.
import { DateTime } from '../py/datetime.mjs';
import { CancelJob } from './errors.mjs';
import { Job } from './job.mjs';

export class Scheduler {
  constructor() {
    this.jobs = [];
  }

  // Runs every job whose next_run has passed, oldest first.
  run_pending() {
    const runnable = this.jobs.filter((job) => job.should_run).sort((a, b) => (a.lt(b) ? -1 : 1));
    for (const job of runnable) this.#runJob(job);
  }

  run_all(delaySeconds = 0) {
    for (const job of [...this.jobs]) {
      this.#runJob(job);
      if (delaySeconds) sleepBusy(delaySeconds);
    }
  }

  // Jobs matching `tag`, or all of them when no tag is given.
  get_jobs(tag = null) {
    if (tag === null) return [...this.jobs];
    return this.jobs.filter((job) => job.tags.has(tag));
  }

  // Deschedules a single job. Removing a job that is already gone is a no-op,
  // mirroring the suppressed ValueError in list.remove().
  cancel_job(job) {
    const index = this.jobs.indexOf(job);
    if (index !== -1) this.jobs.splice(index, 1);
  }

  // Deletes every job, or only the tagged ones.
  clear(tag = null) {
    if (tag === null) {
      this.jobs.length = 0;
    } else {
      this.jobs = this.jobs.filter((job) => !job.tags.has(tag));
    }
  }

  every(interval = 1) {
    return new Job(interval, this);
  }

  #runJob(job) {
    const result = job.run();
    if (result instanceof CancelJob || result === CancelJob) this.cancel_job(job);
  }

  get next_run() {
    if (this.jobs.length === 0) return null;
    return this.jobs.reduce((a, b) => (a.lt(b) ? a : b)).next_run;
  }

  get idle_seconds() {
    if (this.next_run === null) return null;
    return this.next_run.sub(DateTime.now()).totalSeconds();
  }
}

function sleepBusy(seconds) {
  const until = Date.now() + seconds * 1000;
  while (Date.now() < until) {
    /* time.sleep() equivalent for the synchronous run_all() path */
  }
}

