// Public surface of the `schedule` package: the module-level helpers are thin
// delegates onto a single process-wide default_scheduler, exactly as upstream.
import { Scheduler } from './scheduler.mjs';

export { Job } from './job.mjs';
export { Scheduler } from './scheduler.mjs';
export { CancelJob, IntervalError, ScheduleError, ScheduleValueError } from './errors.mjs';

export const default_scheduler = new Scheduler();

export function every(interval = 1) {
  return default_scheduler.every(interval);
}

export function run_pending() {
  default_scheduler.run_pending();
}

export function run_all(delaySeconds = 0) {
  default_scheduler.run_all(delaySeconds);
}

export function get_jobs(tag = null) {
  return default_scheduler.get_jobs(tag);
}

export function clear(tag = null) {
  default_scheduler.clear(tag);
}

export function cancel_job(job) {
  default_scheduler.cancel_job(job);
}

export function next_run() {
  return default_scheduler.next_run;
}

export function idle_seconds() {
  return default_scheduler.idle_seconds;
}

// `jobs` is a module-level alias for the default scheduler's list.
export function jobs() {
  return default_scheduler.jobs;
}

