// argparse's internal error types.
import { PyException } from '../py/exceptions.mjs';

// Raised for a problem with one specific argument; str() prefixes the argument
// name, giving messages like "argument --a: expected one argument".
export class ArgumentError extends PyException {
  constructor(action, message) {
    const name = action ? getActionName(action) : null;
    super(name === null ? message : `argument ${name}: ${message}`, { pyName: 'argparse.ArgumentError' });
    this.argumentName = name;
  }
}

export class ArgumentTypeError extends PyException {
  constructor(message) {
    super(message, { pyName: 'argparse.ArgumentTypeError' });
  }
}

// How an action is named in error messages: joined option strings for
// optionals, metavar or dest for positionals.
export function getActionName(action) {
  if (!action) return null;
  if (action.optionStrings.length > 0) return action.optionStrings.join('/');
  if (action.metavar !== null && action.metavar !== undefined) return action.metavar;
  if (action.dest !== null) return action.dest;
  return null;
}

