// Argument actions. Only the two the script needs: 'store' (the default) and
// 'help'.
import { SystemExit } from '../py/exceptions.mjs';

export class Action {
  constructor({
    optionStrings = [],
    dest,
    nargs = null,
    constant = null,
    defaultValue = null,
    type = null,
    choices = null,
    required = false,
    help = null,
    metavar = null,
  }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.nargs = nargs;
    this.constant = constant;
    this.defaultValue = defaultValue;
    this.type = type;
    this.choices = choices;
    this.required = required;
    this.help = help;
    this.metavar = metavar;
  }

  call(_parser, namespace, values) {
    namespace[this.dest] = values;
  }
}

export class StoreAction extends Action {}

// -h/--help: prints the help text to stdout and exits 0 the moment it is seen,
// before required-argument checking gets a chance to run.
export class HelpAction extends Action {
  constructor(options) {
    super({ ...options, nargs: 0, defaultValue: undefined });
  }

  call(parser) {
    parser.print_help();
    throw new SystemExit(0);
  }
}

