// ArgumentParser: option recognition, value matching, and the error/usage
// reporting that surrounds them.
import { stdoutWrite, stderrWrite, flushStdout } from '../py/io.mjs';
import { SystemExit } from '../py/exceptions.mjs';
import { Action, HelpAction, StoreAction } from './actions.mjs';
import { ArgumentError, getActionName } from './errors.mjs';
import { HelpFormatter } from './formatter.mjs';
import { basename } from 'node:path';

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

export class ArgumentParser {
  constructor({ prog = null, description = null, addHelp = true, allowAbbrev = true, prefixChars = '-' } = {}) {
    // Python defaults prog to the basename of argv[0].
    this.prog = prog ?? basename(process.argv[1] ?? 'prog');
    this.description = description;
    this.allowAbbrev = allowAbbrev;
    this.prefixChars = prefixChars;
    this.actions = [];
    this.optionStringActions = new Map();
    // True only when an option string itself looks like a negative number,
    // which is what decides whether "-5" can be a value.
    this.hasNegativeNumberOptionals = false;

    if (addHelp) {
      this.add_argument('-h', '--help', {
        action: 'help',
        defaultValue: undefined,
        help: 'show this help message and exit',
      });
    }
  }

  // add_argument('--a', { type: String, required: true })
  add_argument(...args) {
    const options = typeof args[args.length - 1] === 'object' ? args.pop() : {};
    const optionStrings = args;
    const {
      action: actionName = 'store',
      dest = null,
      type = null,
      required = false,
      help = null,
      metavar = null,
      defaultValue = null,
      nargs = null,
    } = options;

    // dest comes from the first long option, dashes turned into underscores.
    const longOption = optionStrings.find((s) => s.startsWith('--')) ?? optionStrings[0];
    const resolvedDest = dest ?? longOption.replace(/^-+/, '').replace(/-/g, '_');

    const spec = {
      optionStrings,
      dest: resolvedDest,
      type,
      required,
      help,
      metavar,
      defaultValue,
      nargs,
    };
    const action = actionName === 'help' ? new HelpAction(spec) : new StoreAction(spec);
    this.actions.push(action);
    for (const optionString of optionStrings) {
      this.optionStringActions.set(optionString, action);
      if (NEGATIVE_NUMBER.test(optionString)) this.hasNegativeNumberOptionals = true;
    }
    return action;
  }

  // Parses and rejects anything left over, as parse_args() does.
  parse_args(argv = process.argv.slice(2)) {
    const [namespace, extras] = this.parse_known_args(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  parse_known_args(argv = process.argv.slice(2)) {
    const namespace = {};
    for (const action of this.actions) {
      if (action.defaultValue !== undefined) namespace[action.dest] = action.defaultValue;
    }

    const extras = [];
    const seenActions = new Set();

    // Classify every token: 'O' an option, 'A' a value, '-' the "end of
    // options" marker. Everything after the first '--' is forced to 'A'.
    const optionTuples = new Map();
    const pattern = [];
    let endOfOptions = false;
    for (let i = 0; i < argv.length; i += 1) {
      const token = argv[i];
      if (endOfOptions) {
        pattern.push('A');
        continue;
      }
      if (token === '--') {
        pattern.push('-');
        endOfOptions = true;
        continue;
      }
      const tuple = this.#parseOptional(token);
      if (tuple === null) {
        pattern.push('A');
      } else {
        optionTuples.set(i, tuple);
        pattern.push('O');
      }
    }

    const optionIndices = [...optionTuples.keys()].sort((a, b) => a - b);
    const maxOptionIndex = optionIndices.length > 0 ? optionIndices[optionIndices.length - 1] : -1;

    const takeAction = (action, argumentStrings, optionString) => {
      seenActions.add(action);
      const values = this.#getValues(action, argumentStrings);
      action.call(this, namespace, values, optionString);
    };

    // Consumes the option at `index` plus its values; returns the next index.
    const consumeOptional = (index) => {
      const [action, optionString, explicitArg] = optionTuples.get(index);

      // An option-looking token that matches nothing is simply left over.
      if (action === null) {
        extras.push(argv[index]);
        return index + 1;
      }

      if (explicitArg !== null) {
        // "--a=value": the value is already attached.
        const argCount = this.#matchArgument(action, 'A');
        if (argCount === 1) {
          takeAction(action, [explicitArg], optionString);
          return index + 1;
        }
        throw new ArgumentError(action, `ignored explicit argument '${explicitArg}'`);
      }

      // Otherwise pull values from the following tokens.
      const start = index + 1;
      const argCount = this.#matchArgument(action, pattern.slice(start).join(''));
      const stop = start + argCount;
      takeAction(action, argv.slice(start, stop), optionString);
      return stop;
    };

    // This parser declares no positionals, so any non-option token in between
    // two options goes straight to the leftovers.
    let startIndex = 0;
    while (startIndex <= maxOptionIndex) {
      const nextOptionIndex = optionIndices.find((index) => index >= startIndex);
      if (nextOptionIndex === undefined) break;
      if (startIndex !== nextOptionIndex) {
        extras.push(...argv.slice(startIndex, nextOptionIndex));
        startIndex = nextOptionIndex;
      }
      startIndex = consumeOptional(nextOptionIndex);
    }
    // Trailing tokens — including the '--' marker itself, which no positional
    // action was there to absorb.
    extras.push(...argv.slice(startIndex));

    const missing = this.actions
      .filter((action) => action.required && !seenActions.has(action))
      .map((action) => getActionName(action));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  // _parse_optional(): decides whether a token names an option.
  // Returns null for a value, or [action, optionString, explicitArg].
  #parseOptional(argString) {
    if (!argString) return null; // '' is a positional
    if (!this.prefixChars.includes(argString[0])) return null;
    if (this.optionStringActions.has(argString)) {
      return [this.optionStringActions.get(argString), argString, null];
    }
    if (argString.length === 1) return null; // a bare '-'

    if (argString.includes('=')) {
      const splitAt = argString.indexOf('=');
      const optionString = argString.slice(0, splitAt);
      const explicitArg = argString.slice(splitAt + 1);
      if (this.optionStringActions.has(optionString)) {
        return [this.optionStringActions.get(optionString), optionString, explicitArg];
      }
    }

    const tuples = this.#getOptionTuples(argString);
    if (tuples.length > 1) {
      const matches = tuples.map(([, optionString]) => optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${matches}`);
    }
    if (tuples.length === 1) return tuples[0];

    // "-5" is a value, not an option, unless the parser itself defines
    // negative-number-looking options.
    if (NEGATIVE_NUMBER.test(argString) && !this.hasNegativeNumberOptionals) return null;
    if (argString.includes(' ')) return null;

    // Looks like an option but names nothing: reported as unrecognized.
    return [null, argString, null];
  }

  // Abbreviation matching: '--he' resolves to '--help'.
  #getOptionTuples(argString) {
    const result = [];
    const chars = this.prefixChars;
    if (chars.includes(argString[0]) && chars.includes(argString[1])) {
      let optionPrefix = argString;
      let explicitArg = null;
      if (argString.includes('=')) {
        const splitAt = argString.indexOf('=');
        optionPrefix = argString.slice(0, splitAt);
        explicitArg = argString.slice(splitAt + 1);
      }
      if (!this.allowAbbrev) return result;
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(optionPrefix)) result.push([action, optionString, explicitArg]);
      }
    } else if (chars.includes(argString[0]) && !chars.includes(argString[1])) {
      // Single-dash options may have their value glued on: '-xVALUE'.
      const shortOptionPrefix = argString.slice(0, 2);
      const shortExplicitArg = argString.slice(2);
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString === shortOptionPrefix) {
          result.push([action, optionString, shortExplicitArg]);
        } else if (this.allowAbbrev && optionString.startsWith(argString)) {
          result.push([action, optionString, null]);
        }
      }
    }
    return result;
  }

  // _match_argument(): how many of the following tokens this action takes.
  #matchArgument(action, patternString) {
    const nargs = action.nargs;
    if (nargs === 0) return 0;
    if (nargs === null) {
      // nargs=None wants exactly one value: regex '(-*A-*)' anchored at the
      // start, so an immediately following option string is not a match.
      const match = /^(-*A-*)/.exec(patternString);
      if (match === null) throw new ArgumentError(action, 'expected one argument');
      return match[1].replace(/-/g, '').length + (match[1].length - match[1].replace(/-/g, '').length);
    }
    throw new ArgumentError(action, `unsupported nargs: ${nargs}`);
  }

  // _get_values(): strips the first '--' and applies the type converter.
  #getValues(action, argStrings) {
    const strings = [...argStrings];
    const dashdash = strings.indexOf('--');
    if (dashdash !== -1) strings.splice(dashdash, 1);

    if (action.nargs === 0) return action.constant;
    if (strings.length === 1) return this.#getValue(action, strings[0]);
    return strings.map((value) => this.#getValue(action, value));
  }

  #getValue(action, argString) {
    if (action.type === null || action.type === String) return argString;
    try {
      return action.type(argString);
    } catch {
      const typeName = action.type.name ?? 'value';
      throw new ArgumentError(action, `invalid ${typeName} value: '${argString}'`);
    }
  }

  format_usage() {
    return this.#formatter().formatUsage(this.actions);
  }

  format_help() {
    return this.#formatter().formatHelp(this.actions);
  }

  print_usage(stream = stdoutWrite) {
    stream(this.format_usage());
  }

  print_help(stream = stdoutWrite) {
    stream(this.format_help());
  }

  // error(): usage plus the message on stderr, then exit status 2.
  error(message) {
    this.print_usage(stderrWrite);
    stderrWrite(`${this.prog}: error: ${message}\n`);
    this.exit(2);
  }

  exit(status = 0, message = null) {
    if (message) stderrWrite(message);
    flushStdout();
    throw new SystemExit(status);
  }

  #formatter() {
    return new HelpFormatter(this.prog);
  }
}

