// linecache: resolves the source line a traceback frame points at.
//
// Frames name their file the way the interpreter saw it — often relative, e.g.
// "test10.py" — and linecache resolves that against the current working
// directory. That is why a traceback shows the offending source line when run
// from the script's own directory and omits it from anywhere else, and why the
// frozen build never shows lines for its bundled packages.
import { readFileSync } from 'node:fs';

const cache = new Map();

// Returns the 1-indexed line, or '' when the file cannot be found.
export function getline(filename, lineno) {
  const lines = getlines(filename);
  if (lineno < 1 || lineno > lines.length) return '';
  return lines[lineno - 1];
}

export function getlines(filename) {
  if (cache.has(filename)) return cache.get(filename);
  let lines = [];
  try {
    lines = readFileSync(filename, 'utf8').split('\n');
  } catch {
    lines = []; // no such file: linecache yields nothing
  }
  cache.set(filename, lines);
  return lines;
}

