// Renders an unhandled exception the way the frozen CPython binary does.
//
// Python 3.11+ prints fine-grained error locations: below the offending source
// line comes a caret run underlining just the sub-expression that raised. Both
// the source line and its carets are omitted whenever linecache cannot find the
// file — which is the norm for the frozen build's bundled packages, and for the
// script itself unless the cwd happens to hold it.
import { stderrWrite, flushStdout } from './io.mjs';
import { getline } from './linecache.mjs';

const SOURCE_INDENT = '    ';

// frames: [{ file, line, func, mark? }] outermost first. `mark` is the
// sub-expression the carets should underline.
export function printException(exception, frames) {
  let out = 'Traceback (most recent call last):\n';
  for (const frame of frames) {
    out += `  File "${frame.file}", line ${frame.line}, in ${frame.func}\n`;

    const source = getline(frame.file, frame.line).trim();
    if (!source) continue;
    out += `${SOURCE_INDENT}${source}\n`;

    if (!frame.mark) continue;
    const column = source.indexOf(frame.mark);
    // Carets are only drawn when the raising expression is a strict part of the
    // statement; a whole-line span gets no underline.
    if (column >= 0 && frame.mark.length < source.length) {
      out += `${SOURCE_INDENT}${' '.repeat(column)}${'^'.repeat(frame.mark.length)}\n`;
    }
  }
  out += `${exception.pyName}: ${exception.message}\n`;
  stderrWrite(out);
}

// The PyInstaller bootloader's own epilogue, emitted after the traceback.
export function printBootloaderFailure(scriptName) {
  stderrWrite(`[PYI-${process.pid}:ERROR] Failed to execute script '${scriptName}' due to unhandled exception!\n`);
}

// Interpreter shutdown drains stdout *after* stderr already carried the
// traceback, which is why redirecting both into one pipe shows them in that
// order.
export function terminate(status) {
  flushStdout();
  process.exitCode = status;
}

