// argparse's HelpFormatter: usage line, option list, and the column arithmetic
// that decides whether an option's help text starts on the same line.

// shutil.get_terminal_size(): COLUMNS wins, then the real terminal, then 80x24.
export function terminalColumns() {
  const fromEnv = parseInt(process.env.COLUMNS ?? '', 10);
  if (!Number.isNaN(fromEnv) && fromEnv > 0) return fromEnv;
  if (process.stdout.isTTY && process.stdout.columns > 0) return process.stdout.columns;
  return 80;
}

export class HelpFormatter {
  constructor(prog, { indentIncrement = 2, maxHelpPosition = 24, width = null } = {}) {
    this.prog = prog;
    this.indentIncrement = indentIncrement;
    // argparse asks for two columns less than the terminal width.
    this.width = width ?? terminalColumns() - 2;
    this.maxHelpPosition = Math.min(maxHelpPosition, Math.max(this.width - 20, indentIncrement * 2));
    this.currentIndent = indentIncrement; // actions always live inside a section
  }

  // "usage: prog [-h] --a A", wrapped once it outgrows the terminal.
  formatUsage(actions) {
    const prefix = 'usage: ';
    const optionalParts = actions.map((action) => this.#usagePart(action));
    let usage = [this.prog, ...optionalParts].filter(Boolean).join(' ');

    const textWidth = this.width - 0;
    if (prefix.length + usage.length > textWidth) {
      // Split into wrappable pieces. Bracketed groups stay whole; everything
      // else breaks on whitespace, so "--a A" can be split across lines.
      const parts = optionalParts.flatMap((part) =>
        part.startsWith('[') || part.startsWith('(') ? [part] : part.split(' ')
      );
      let lines;
      if (prefix.length + this.prog.length <= 0.75 * textWidth) {
        // Short prog: the first option group shares its line.
        const indent = ' '.repeat(prefix.length + this.prog.length + 1);
        lines = wrapParts([this.prog, ...parts], indent, textWidth, prefix);
        lines[0] = this.prog;
      } else {
        // Long prog: it gets a line of its own.
        const indent = ' '.repeat(prefix.length);
        lines = [this.prog, ...wrapParts(parts, indent, textWidth, null)];
      }
      usage = lines.join('\n');
    }
    return `${prefix}${usage}\n\n`;
  }

  // The full help text: usage, then one section per non-empty action group.
  formatHelp(actions, sectionTitle = 'options') {
    const helpPosition = Math.min(this.#actionMaxLength(actions) + 2, this.maxHelpPosition);
    const helpWidth = Math.max(this.width - helpPosition, 11);
    const actionWidth = helpPosition - this.currentIndent - 2;

    let body = '';
    for (const action of actions) {
      const header = this.formatActionInvocation(action);
      if (!action.help) {
        // No help text: the invocation is the whole line.
        body += `${' '.repeat(this.currentIndent)}${header}\n`;
        continue;
      }
      const helpLines = wrapText(action.help, helpWidth);
      if (header.length <= actionWidth) {
        // Short invocation: help starts on the same line, two spaces over.
        body += `${' '.repeat(this.currentIndent)}${header.padEnd(actionWidth)}  ${helpLines[0]}\n`;
        for (const line of helpLines.slice(1)) body += `${' '.repeat(helpPosition)}${line}\n`;
      } else {
        // Long invocation: help is pushed to the following lines.
        body += `${' '.repeat(this.currentIndent)}${header}\n`;
        for (const line of helpLines) body += `${' '.repeat(helpPosition)}${line}\n`;
      }
    }

    let help = this.formatUsage(actions);
    if (body) help += `${sectionTitle}:\n${body}`;
    return normalizeHelp(help);
  }

  // "-h, --help" for flags, "--a A" for options that take a value.
  formatActionInvocation(action) {
    if (action.nargs === 0) return action.optionStrings.join(', ');
    const args = this.#formatArgs(action);
    return action.optionStrings.map((option) => `${option} ${args}`).join(', ');
  }

  // How the action appears in the usage line: bracketed unless required.
  #usagePart(action) {
    const optionString = action.optionStrings[0];
    const part = action.nargs === 0 ? optionString : `${optionString} ${this.#formatArgs(action)}`;
    return action.required ? part : `[${part}]`;
  }

  #formatArgs(action) {
    return action.metavar ?? action.dest.toUpperCase();
  }

  // Longest invocation, indent included — this is what sets the help column.
  #actionMaxLength(actions) {
    let max = 0;
    for (const action of actions) {
      max = Math.max(max, this.formatActionInvocation(action).length + this.currentIndent);
    }
    return max;
  }
