#!/usr/bin/env node
// Randomised differential fuzz over argument shapes.
import { execFileSync } from 'node:child_process';

const REF = '/workspace/dataset/test10_executable';

const TOKENS = [
  '--a', '--b', '--c', '--d', '--h', '--he', '--help', '-h', '-a', '-x', '--',
  '--a=10:30', '--b=', '--a=', '10:30', '10:30:45', '25:00', '0:0', ':5', '-5', '-3.5',
  '', ' ', 'x', 'y', 'z', '--e', '--a=1=2', '23:59:59', 'héllo', 'a b', '--a=--b',
];

function run(cmd, args, argv) {
  try {
    const stdout = execFileSync(cmd, [...args, ...argv], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    return { code: 0, stdout, stderr: '' };
  } catch (err) {
    return { code: err.status, stdout: err.stdout ?? '', stderr: err.stderr ?? '' };
  }
}

const normalize = (text) => text.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');

let checked = 0;
let failures = 0;
const seen = new Set();
for (let trial = 0; trial < 700; trial += 1) {
  const count = 1 + Math.floor(Math.random() * 7);
  const argv = Array.from({ length: count }, () => TOKENS[Math.floor(Math.random() * TOKENS.length)]);
  const key = JSON.stringify(argv);
  if (seen.has(key)) continue;
  seen.add(key);

  const ref = run(REF, [], argv);
  const port = run('node', ['/output/test10.mjs'], argv);
  checked += 1;

  const same =
    ref.stdout === port.stdout &&
    normalize(ref.stderr) === normalize(port.stderr) &&
    ref.code === port.code;
  if (!same) {
    failures += 1;
    console.log(`FAIL argv=${key}`);
    console.log(`  ref  exit=${ref.code}\n    out=${JSON.stringify(ref.stdout)}\n    err=${JSON.stringify(normalize(ref.stderr))}`);
    console.log(`  port exit=${port.code}\n    out=${JSON.stringify(port.stdout)}\n    err=${JSON.stringify(normalize(port.stderr))}`);
    if (failures >= 8) break;
  }
}
console.log(`fuzz: ${checked} unique argv vectors, ${failures} failures`);

