export function partial(func, args = [], keywords = new Map()) {
  const bound = keywords instanceof Map ? keywords : new Map(Object.entries(keywords));
  // JS has no keyword arguments, so non-empty keywords are handed over as a
  // trailing options object; the common empty case adds nothing.
  const wrapper = (...extra) =>
    bound.size > 0
      ? func(...args, ...extra, Object.fromEntries(bound))
      : func(...args, ...extra);
  wrapper.func = func;
  wrapper.args = args;
  wrapper.keywords = bound;
  return wrapper;
}

