// Smoke test for the parts of the schedule library the ported script does not
// reach, checking they behave rather than throw.
import * as schedule from '/output/lib/schedule/index.mjs';
import { Scheduler, IntervalError, CancelJob } from '/output/lib/schedule/index.mjs';
import { print, pyStr, len } from '/output/lib/py/builtins.mjs';
import { lambda } from '/output/lib/py/functools.mjs';

const named = (name, fn) => Object.assign(fn, { __name__: name });
let failures = 0;
const check = (label, actual, expected) => {
  const ok = actual === expected;
  if (!ok) failures += 1;
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}${ok ? '' : `\n   want ${JSON.stringify(expected)}\n   got  ${JSON.stringify(actual)}`}`);
};

const s = new Scheduler();

// str() with a real function name, positional args and keyword args.
const job = s.every(2).seconds.do(named('greet', () => null), [1, 'two'], new Map([['k', 3]]));
check('str(): interval/args/kwargs', pyStr(job),
  "Job(interval=2, unit=seconds, do=greet, args=(1, 'two'), kwargs={'k': 3})");

// Singular units are rejected when the interval is not 1.
let raised = null;
try { s.every(5).second; } catch (err) { raised = err; }
check('every(5).second raises', raised instanceof IntervalError, true);
check('  message', raised?.message, 'Use seconds instead of second');
check('  pyName', raised?.pyName, 'schedule.IntervalError');

// Hourly and minutely at() formats.
check('hours at :30 accepted', pyStr(s.every().hours.at('05:30').at_time), '00:05:30');
check('minutes at :09 accepted', pyStr(s.every().minutes.at(':09').at_time), '00:00:09');
let hourlyError = null;
try { s.every().hours.at('99:99'); } catch (err) { hourlyError = err; }
check('hourly bad format', hourlyError?.message,
  'Invalid time format for an hourly job (valid format is (MM)?:SS)');

// Weekday jobs schedule into the future on the right day.
const weekly = s.every().monday.at('09:00').do(lambda(() => null));
check('monday job unit', weekly.unit, 'weeks');
check('monday job start_day', weekly.start_day, 'monday');
check('monday next_run is a Monday', weekly.next_run.date.getDay(), 1);
check('monday next_run is future', weekly.next_run.date.getTime() > Date.now(), true);

// Tags filter get_jobs()/clear().
s.clear();
s.every().seconds.do(lambda(() => null)).tag('keep');
s.every().seconds.do(lambda(() => null)).tag('drop');
check('get_jobs(tag)', len(s.get_jobs('keep')), 1);
s.clear('drop');
check('clear(tag)', len(s.get_jobs()), 1);

// run_pending() runs due jobs; returning CancelJob deschedules them.
s.clear();
let runs = 0;
const due = s.every().seconds.do(lambda(() => { runs += 1; return new CancelJob(); }));
due.next_run = due.next_run.sub(due.period).sub(due.period); // force it overdue
check('should_run when overdue', due.should_run, true);
s.run_pending();
check('run_pending ran it', runs, 1);
check('CancelJob descheduled it', len(s.get_jobs()), 0);

// repr() differs from str(): it reports the human-readable schedule.
s.clear();
const daily = s.every().days.at('06:00').do(named('backup', () => null));
check('repr() shape', /^Every 1 day at 06:00:00 do backup\(\) \(last run: \[never\], next run: \d{4}-\d\d-\d\d 06:00:00\)$/.test(daily.__repr__()), true);

// idle_seconds/next_run on the default scheduler.
schedule.clear();
schedule.every(3).hours.do(lambda(() => null));
check('default next_run set', schedule.next_run() !== null, true);
check('idle_seconds ~3h', Math.round(schedule.idle_seconds() / 60), 180);
check('module clear()', (schedule.clear(), len(schedule.get_jobs())), 0);

// print() of a job goes through __str__.
print(daily);

console.log(failures === 0 ? '\nall library smoke checks passed' : `\n${failures} failures`);
process.exitCode = failures === 0 ? 0 : 1;

